head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#f4f1e5" value="#f4f1e5"/><Variable name="page.text" description="Text color" type="color" default="#242a24" value="#242a24"/><Variable name="theme.accent" description="Accent color" type="color" default="#963b2e" value="#963b2e"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Libre Baskerville', Georgia, serif;--body:Arial, sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
.site-header{margin:0 4%;padding-top:20px}.paper-strap{display:flex;justify-content:space-between;font-size:10px;letter-spacing:.5px;border-bottom:1px solid;padding-bottom:12px}.paper-masthead{text-align:center;font:bold clamp(52px,7.4vw,100px)/1.3 'Libre Baskerville', Georgia,serif;letter-spacing:-5px;padding:10px 0}nav{display:flex;justify-content:center;gap:40px;border-top:3px double;border-bottom:1px solid;padding:13px 0;font-size:11px;text-transform:uppercase;letter-spacing:1px}.news-front{display:grid;grid-template-columns:2.5fr 1fr;gap:28px;margin:35px 4%}.news-label{color:#963b2e;font-size:10px;letter-spacing:1.5px;font-weight:700}.news-main h1{font:bold clamp(39px,4.7vw,63px)/1.03 'Libre Baskerville', Georgia,serif;letter-spacing:-2px;margin:20px 0}.news-deck{font:18px/1.5 'Libre Baskerville', Georgia,serif;max-width:610px}.news-main figure{margin:25px 0 18px}.news-main svg{width:100%;display:block}.news-main figcaption{font-size:8px;letter-spacing:1px;margin-top:8px}.news-leadlink{font-size:12px;font-weight:bold}.news-sidebar{border-left:1px solid #b4b3a4;padding-left:24px}.news-sidebar article{border-bottom:1px solid #b4b3a4;padding:22px 0}.news-sidebar article>span{font-size:9px;letter-spacing:1px}.news-sidebar h2{font:bold 26px/1.12 'Libre Baskerville', Georgia,serif}.news-sidebar article p{font:14px/1.65 'Libre Baskerville', Georgia,serif}.news-sidebar a{font-size:10px;font-weight:bold}.news-strip{margin:35px 4%;border-top:3px double;border-bottom:1px solid;padding:18px 0;display:flex;justify-content:space-between;gap:20px;font-size:10px}.news-strip strong{color:#963b2e}.news-principles{margin:38px 4%}.news-principles h2{font:italic 32px 'Libre Baskerville', Georgia,serif}.news-principles>div{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.news-principles p{font:14px/1.7 'Libre Baskerville', Georgia,serif;border-left:3px solid #963b2e;padding-left:18px}.news-principles b{font-size:18px}.latest{margin:45px 4%}.section-heading{font:bold 32px 'Libre Baskerville', Georgia,serif;border-top:3px double;padding-top:22px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.post-card{border-right:1px solid #b4b3a4;padding-right:25px}.post-card:last-child{border:0}.post-media{aspect-ratio:16/9;object-fit:cover;background:#d8d8c9;filter:grayscale(1)}.post-meta{font-size:9px;text-transform:uppercase;letter-spacing:1px;color:#963b2e}.post-title{font:bold 26px/1.13 'Libre Baskerville', Georgia,serif}.post-excerpt{font:14px/1.65 'Libre Baskerville', Georgia,serif}.news-standards{margin:55px 4% 0;padding:35px;border:1px solid;display:grid;grid-template-columns:1fr 1.4fr;gap:20px}.news-standards>span{font-size:9px;letter-spacing:2px;grid-column:1/-1}.news-standards h2{font:bold 39px/1.08 'Libre Baskerville', Georgia,serif;margin:0}.news-standards p{font:15px/1.8 'Libre Baskerville', Georgia,serif;margin:0}.news-standards a{font-size:11px;font-weight:bold;grid-column:2}.site-footer{margin:25px 4%;border-top:3px double;padding:25px 0;display:flex;justify-content:space-between;gap:20px;font-size:10px}.site-footer strong{font:bold 24px 'Libre Baskerville', Georgia,serif}a:hover,a:focus-visible{text-decoration:underline}@media(max-width:700px){.paper-masthead{letter-spacing:-3px;font-size:50px}nav{gap:17px;flex-wrap:wrap}.news-front{grid-template-columns:1fr}.news-sidebar{border-left:0;border-top:1px solid;padding-left:0;display:grid;grid-template-columns:1fr 1fr;gap:20px}.news-sidebar>.news-label{grid-column:1/-1}.news-sidebar article{padding:0}.news-strip{flex-wrap:wrap}.news-principles>div,.posts-grid{grid-template-columns:1fr}.post-card{border-right:0;border-bottom:1px solid;padding:0 0 25px}.news-standards{grid-template-columns:1fr;padding:25px}.news-standards a{grid-column:auto}.site-footer{flex-direction:column}}
:focus-visible{outline:2px solid currentColor;outline-offset:5px}img,svg{max-width:100%}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
h1,h2,h3{font-family:'Libre Baskerville', Georgia, serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
